a = {"vendor": "A", "id": "AMR-07", "battery_pct": 23, "state": "IDLE"}
b = {"vendor": "B", "robotName": "COBOT-2", "soc": 0.81, "mode": "RUNNING"}
def norm(m):
    if m["vendor"] == "A":
        return (m["id"], m["battery_pct"], m["state"].lower())
    return (m["robotName"], round(m["soc"] * 100), {"RUNNING": "busy"}.get(m["mode"], m["mode"].lower()))
for r in map(norm, [a, b]):
    print(r, "-> 충전 보냄" if r[1] < 30 and r[2] == "idle" else "-> 그대로")
# ('AMR-07', 23, 'idle') -> 충전 보냄
# ('COBOT-2', 81, 'busy') -> 그대로

base = {"/Fab/Bay1/Robot01.pos": (0, 0, 0), "/Fab/Bay1/Robot01.color": "gray", "/Fab/Bay1/Chiller.temp": 0.0}
layout = {"/Fab/Bay1/Robot01.pos": (12.5, 3.0, 0)}
live = {"/Fab/Bay1/Chiller.temp": 18.4}
def compose(*layers_strong_first):
    out = {}
    for layer in reversed(layers_strong_first):
        out.update(layer)
    return out
for k, v in compose(live, layout, base).items():
    print(k, "=", v)
